public void initFromNDXPOPspecificDataManagementLine(NDXPOPspecificDataManagementLine _nDXPOPspecificDataManagementLine)
{
    SysDictTable dictTable = new SysDictTable(tableNum(NDXPOPspecificDataManagementLine));
    FieldId fieldIdTransferLine;
    FieldId fieldIdLine;
    str fieldName;
    SysDictFieldGroup dictFieldGroup = new SysDictFieldGroup(tableNum(NDXPOPspecificDataManagementLineTransfer), tableFieldGroupStr(NDXPOPspecificDataManagementLineTransfer, ChangeableFields));
    for (int i = 1; i <= dictFieldGroup.numberOfFields(); i++)
    {
        fieldIdTransferLine = dictFieldGroup.field(i);
        fieldName = fieldId2Name(tableNum(NDXPOPspecificDataManagementLineTransfer), fieldIdTransferLine);
        fieldIdLine = dictTable.fieldName2Id(fieldName);
        this.(fieldIdTransferLine) = _nDXPOPspecificDataManagementLine.(fieldIdLine);
    }
}
